const look = ['panes', 'navigate', 'snapshot', 'screenshot', 'scroll', 'read', 'find', 'handoff'];
const act = [...look, 'back', 'click', 'type', 'key', 'select', 'wait_for', 'dialog', 'batch'];
/** Browser tool presets, each holding the one before it. */
export const PRESETS                           = { look, act, debug: [...act, 'console', 'network', 'evaluate'] };

export const isPreset = (name         )                 => typeof name === 'string' && Object.hasOwn(PRESETS, name);

/** The smallest preset holding the tool, or null. */
export const smallestPreset = (tool        )                => Object.keys(PRESETS).find((n) => PRESETS[n].includes(tool)) ?? null;
